Consider the following ANSI C program<pre><code> #include &lt;stdio.h&gt;
int foo(int x, int y, int q) 
    {
        if ((x &lt;= 0) && (y &lt;= 0))
        return q;
        if (x &lt;= 0)
        return foo(x, y-q, q);
        if (y &lt;= 0)
        return foo(x-q, y, q);
        return foo(x, y-q, q) + foo(x-q, y, q);
    }
int main( )
{
    int r = foo(15, 15, 10);
    printf("%d", r);
    return 0;
}</code></pre>  The output of the program upon execution is ____
